  /**
 * Registers a new block provided a unique name and an object defining its behavior.
 */
import { registerBlockType } from '@wordpress/blocks';
import './style.scss';
import Edit from './edit';
import save from './save';
import metadata from './block.json';

registerBlockType( metadata.name, {
	edit: Edit,
	save,
} );

import { __ } from '@wordpress/i18n';
import { useBlockProps } from '@wordpress/block-editor';
import { useEffect } from '@wordpress/element';

const KAOMOJIS = [
	"(´・ω・`)",
	"(｡･ω･｡)",
	"(＾▽＾)",
	"(；´∀｀)",
	"(｀・ω・´)",
	"( ´∀｀)",
	"(￣ー￣)",
	"(*´ω｀*)",
	"＼(^o^)／",
	"(T_T)",
	"(^_^;)",
	"(╯°□°）╯︵ ┻━┻",
	"(・∀・)",
	"(´Д｀)",
	"(¬_¬)",
	"(ﾟ∀ﾟ)",
	"( ˘ω˘ )",
	"٩( 'ω' )و",
	"(￣^￣)ゞ",
	"(⌒▽⌒)",
];

export default function Edit( { attributes, setAttributes, isSelected } ) {
	const { kaomoji = "" } = attributes;

	useEffect(() => {
		// Set default if not set
		if (!kaomoji && KAOMOJIS.length > 0) {
			setAttributes( { kaomoji: KAOMOJIS[0] } );
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);

	const handleSelect = (emoji) => {
		setAttributes( { kaomoji: emoji } );
	};

	return (
		<div { ...useBlockProps() }>
			<div className="kaomoji-selector__current" style={{ fontSize: "2rem", marginBottom: ".5em" }}>
				{ kaomoji ? kaomoji : __( "顔文字を選択してください", "kaomoji-selector-block-wp" ) }
			</div>
			<div className="kaomoji-selector__list" style={{ display: "flex", flexWrap: "wrap", gap: ".2em" }}>
				{ KAOMOJIS.map( (item) => (
					<button
						type="button"
						key={item}
						onClick={ () => handleSelect(item) }
						aria-pressed={ kaomoji === item }
						className={ "kaomoji-selector__button" + (kaomoji === item ? " is-selected" : "" ) }
						style={{
							padding: "0.2em 0.5em",
							fontSize: "1.3em",
							border: kaomoji === item ? "2px solid #21759b" : "1px solid #ddd",
							borderRadius: "3px",
							cursor: "pointer",
							background: kaomoji === item ? "#eaf6fb" : "#fff",
							transition: "border .15s"
						}}
					>{item}</button>
				))}
			</div>
		</div>
	);
}

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 */
import { useBlockProps } from '@wordpress/block-editor';

export default function save( { attributes } ) {
	const { kaomoji = "" } = attributes;
	return (
		<div { ...useBlockProps.save() }>
			<span className="kaomoji-selector__output" style={{ fontSize: "2rem" }}>
				{ kaomoji }
			</span>
		</div>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 */

.wp-block-w0-kaomoji-selector {
	text-align: center;
}

.kaomoji-selector__output {
	font-family: inherit;
	display: inline-block;
}

.kaomoji-selector__current {
	font-weight: bold;
}

.kaomoji-selector__button.is-selected {
	box-shadow: 0 0 3px 2px #cce6f2;
}

.wp-block-w0-kaomoji-selector {
	border: 1px dashed #21759b;
	padding: 1em;
	background: #f8fbfc;
}
.kaomoji-selector__button:focus {
	outline: 2px solid #21759b;
}

/**
 * Use this file for JavaScript code that you want to run in the front-end
 * on posts/pages that contain this block.
 */
console.log("Hello World! (from w0-kaomoji-selector block)");
